import 'dart:convert'  import 'dart:io'  import 'package:dio/dio.dart'  import 'package:flutter/foundation.dart'  import 'package:hive/hive.dart'    /// API клиент для Мир Самозанятых v8.5  /// АНО ЦПС ИНН 9724016805  class ApiClient {    static final ApiClient _instance = ApiClient._internal()    factory ApiClient() => _instance    ApiClient._internal()    late final Dio _dio    static const String _baseUrl = 'https://api.mir-samozanyatykh.ru'    static const String _tokenKey = 'auth_token'    static const String _refreshTokenKey = 'refresh_token'      void init() {      _dio = Dio(BaseOptions(        baseUrl: _baseUrl,        connectTimeout: const Duration(seconds: 15),        receiveTimeout: const Duration(seconds: 15),        headers: {'Content-Type': 'application/json'},      ))        _dio.interceptors.add(InterceptorsWrapper(        onRequest: (options, handler) async {          final token = await _getToken()          if (token != null) {            options.headers['Authorization'] = 'Bearer $token'          }          if (kDebugMode) {            print('→ ${options.method} ${options.path}')          }          handler.next(options)        },        onResponse: (response, handler) {          if (kDebugMode) {            print('← ${response.statusCode} ${response.requestOptions.path}')          }          handler.next(response)        },        onError: (error, handler) async {          if (error.response?.statusCode == 401) {            final refreshed = await _refreshToken()            if (refreshed) {              final token = await _getToken()              error.requestOptions.headers['Authorization'] = 'Bearer $token'              final retry = await _dio.fetch(error.requestOptions)              handler.resolve(retry)              return            }          }          handler.next(error)        },      ))    }      Future<String?> _getToken() async {      final box = await Hive.openBox<String>('auth')      return box.get(_tokenKey)    }      Future<bool> _refreshToken() async {      final box = await Hive.openBox<String>('auth')      final refreshToken = box.get(_refreshTokenKey)      if (refreshToken == null) return false        try {        final response = await _dio.post('/api/auth/refresh', data: {'refresh_token': refreshToken})        final newToken = response.data['access_token'] as String?        final newRefresh = response.data['refresh_token'] as String?        if (newToken != null) await box.put(_tokenKey, newToken)        if (newRefresh != null) await box.put(_refreshTokenKey, newRefresh)        return true      } catch {        await box.delete(_tokenKey)        await box.delete(_refreshTokenKey)        return false      }    }      // ============ AUTH ============    Future<Map<String, dynamic>> login(String email, String password) async {      final response = await _dio.post('/api/auth/login', data: {'email': email, 'password': password})      final token = response.data['access_token'] as String?      final refresh = response.data['refresh_token'] as String?      if (token != null) {        final box = await Hive.openBox<String>('auth')        await box.put(_tokenKey, token)        if (refresh != null) await box.put(_refreshTokenKey, refresh)      }      return response.data    }      Future<Map<String, dynamic>> register(Map<String, dynamic> data) async {      final response = await _dio.post('/api/auth/register', data: data)      return response.data    }      Future<void> logout() async {      final box = await Hive.openBox<String>('auth')      await box.delete(_tokenKey)      await box.delete(_refreshTokenKey)    }      Future<bool> isAuthenticated() async {      final token = await _getToken()      return token != null    }      // ============ DASHBOARD ============    Future<Map<String, dynamic>> getDashboardStats() async {      final [sales, crm, notif] = await Future.wait([        _dio.get('/api/sales/stats'),        _dio.get('/api/crm/stats'),        _dio.get('/api/notifications/unread-count'),      ])      return {        'sales': sales.data,        'crm': crm.data,        'unread': notif.data['unread_count'] ?? 0,      }    }      // ============ CLIENTS ============    Future<List<dynamic>> getClients() async {      final response = await _dio.get('/api/crm/clients')      return response.data as List<dynamic>    }      Future<Map<String, dynamic>> createClient(Map<String, dynamic> data) async {      final response = await _dio.post('/api/crm/clients', data: data)      return response.data    }      // ============ DEALS ============    Future<List<dynamic>> getDeals() async {      final response = await _dio.get('/api/crm/deals')      return response.data as List<dynamic>    }      Future<List<dynamic>> getPipelineStages() async {      final response = await _dio.get('/api/crm/pipeline-stages')      return response.data as List<dynamic>    }      Future<Map<String, dynamic>> createDeal(Map<String, dynamic> data) async {      final response = await _dio.post('/api/crm/deals', data: data)      return response.data    }      Future<void> moveDeal(int dealId, int stageId) async {      await _dio.post('/api/crm/deals/$dealId/move?stage_id=$stageId')    }      // ============ INVOICES ============    Future<List<dynamic>> getInvoices() async {      final response = await _dio.get('/api/sales/invoices')      return response.data as List<dynamic>    }      Future<Map<String, dynamic>> createInvoice(Map<String, dynamic> data) async {      final response = await _dio.post('/api/sales/invoices', data: data)      return response.data    }      // ============ TASKS ============    Future<List<dynamic>> getTasks() async {      final response = await _dio.get('/api/crm/tasks')      return response.data as List<dynamic>    }      Future<Map<String, dynamic>> createTask(Map<String, dynamic> data) async {      final response = await _dio.post('/api/crm/tasks', data: data)      return response.data    }      Future<void> completeTask(int taskId) async {      await _dio.put('/api/crm/tasks/$taskId', data: {'status': 'completed'})    }      // ============ NOTIFICATIONS ============    Future<List<dynamic>> getNotifications() async {      final response = await _dio.get('/api/notifications/')      return response.data as List<dynamic>    }      Future<void> markNotificationRead(int id) async {      await _dio.put('/api/notifications/$id/read')    }      Future<void> markAllRead() async {      await _dio.put('/api/notifications/read-all')    }      // ============ BANK ============    Future<List<dynamic>> getBankConnections() async {      final response = await _dio.get('/api/bank/connections')      return response.data as List<dynamic>    }      Future<Map<String, dynamic>> syncBank(int connectionId) async {      final response = await _dio.post('/api/bank/sync/$connectionId')      return response.data    }      // ============ PROFILE ============    Future<Map<String, dynamic>> getProfile() async {      final response = await _dio.get('/api/users/me')      return response.data    }      Future<Map<String, dynamic>> updateProfile(Map<String, dynamic> data) async {      final response = await _dio.put('/api/users/me', data: data)      return response.data    }      // ============ UTILS ============    Dio get dio => _dio  }